using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change #1: Discriminator property renamed to "$type".
            // Preserve EF8 behavior for existing 500K documents that use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change #2: Id format changed from "EntityType|Key" to just the key.
            // Preserve EF8 format "Product|123" for existing documents.
            entity.HasIdProperty("id", id => id.HasValueGenerator<LegacyIdValueGenerator>());

            // EF Core 9 breaking change #3: Vectors/indexing API changes — HasIndex is no longer
            // supported for Cosmos; use Cosmos-specific indexing in OnModelCreating instead.
        });
    }
}

